function wholesale_panel(): void {
 $u=current_user();if(!$u)redirect('/login');
 $q=is_string($_GET['q']??null)?trim(mb_substr($_GET['q'],0,80)):'';$category=isset($_GET['category'])?number_input('category',0,PHP_INT_MAX,$_GET):0;
 $sql='SELECT p.*,c.name category_name FROM ns_products p JOIN ns_categories c ON c.id=p.category_id WHERE p.active=1 AND EXISTS (SELECT 1 FROM ns_product_sales s WHERE s.product_id=p.id AND s.sale_type=\'wholesale\')';$args=[];if($category){$sql.=' AND p.category_id=?';$args[]=$category;}if($q!==''){$sql.=' AND (p.name LIKE ? OR c.name LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$products=all($sql.' ORDER BY p.stock>0 DESC,p.featured DESC,p.id DESC LIMIT 200',$args);
 $orders=all("SELECT code,status,total,created_at FROM ns_orders WHERE user_id=? ORDER BY id DESC LIMIT 8",[$u['id']]);$paid=one("SELECT COUNT(*) orders_count,COALESCE(SUM(total),0) total FROM ns_orders WHERE user_id=? AND status IN ('PAID','SHIPPED','DELIVERED')",[$u['id']]);$cart=cart_lines();$cartCount=0;$cartSaving=0;foreach($cart as$line)if(empty($line['missing'])){$cartCount+=(int)$line['quantity'];if((int)$line['quantity']>=(int)$line['minimum'])$cartSaving+=((int)$line['retail']-(int)$line['wholesale'])*(int)$line['quantity'];}
 page_header('پنل فروش عمده','',false,url('/wholesale-panel'));
 ?><div class="container page-content wholesale-dashboard"><header class="wholesale-head"><div><span class="status">پنل خرید عمده</span><h1>سلام <?=h($u['name'])?>، پنل فروش عمده شما آماده است</h1><p>برای هر محصول با رسیدن تعداد به آستانه درج‌شده، قیمت عمده خودکار اعمال می‌شود. مبلغ نهایی و موجودی هنگام تسویه دوباره در سرور کنترل خواهد شد.</p></div><div class="buy-row"><a class="btn" href="/cart">سبد عمده · <?=money($cartCount)?> کالا</a><a class="btn outline" href="/shipping">روش‌های ارسال</a></div></header>
 <section class="wholesale-stats"><article class="panel"><small>خریدهای پرداخت‌شده</small><strong><?=money($paid['orders_count']??0)?></strong><span>سفارش</span></article><article class="panel"><small>ارزش خریدهای ثبت‌شده</small><strong><?=money($paid['total']??0)?></strong><span>تومان</span></article><article class="panel"><small>صرفه‌جویی سبد فعلی</small><strong><?=money($cartSaving)?></strong><span>تومان</span></article><article class="panel"><small>روش محاسبه</small><strong>خودکار</strong><span>بر اساس آستانه هر محصول</span></article></section>
 <nav class="wholesale-shortcuts panel" aria-label="دسترسی سریع"><a href="#quick-order">سفارش سریع</a><a href="#wholesale-catalog">لیست قیمت عمده</a><a href="#recent-orders">سفارش‌های اخیر</a><a href="/track">پیگیری سفارش</a><a href="/contact">پشتیبانی فروش عمده</a></nav>
 <section id="quick-order" class="panel wholesale-quick"><div class="section-heading"><div><span class="eyebrow">ثبت سریع تعداد</span><h2>سفارش سریع عمده</h2></div><a href="/cart">مشاهده سبد و جمع نهایی ←</a></div><div class="table-scroll"><table><thead><tr><th>محصول</th><th>موجودی</th><th>قیمت مصرف‌کننده</th><th>قیمت همکاری شما</th><th>صرفه‌جویی واحد</th><th>تعداد در سبد</th></tr></thead><tbody><?php foreach(array_slice($products,0,12)as$p):?><tr><td><a href="/products/<?=h($p['slug'])?>"><strong><?=h($p['name'])?></strong><small><?=h($p['category_name'])?> · هر <?=h($p['unit'])?></small></a></td><td><?=$p['stock']?money($p['stock']).' '.$p['unit']:'ناموجود'?></td><td><del><?=money($p['retail'])?></del></td><td><strong><?=money($p['wholesale'])?> تومان</strong></td><td><?=money((int)$p['retail']-(int)$p['wholesale'])?> تومان</td><td><?php quantity_control($p,true);?></td></tr><?php endforeach;?></tbody></table></div></section>
 <section id="wholesale-catalog"><div class="section-heading"><div><span class="eyebrow">قابل سفارش برای همه مشتریان</span><h2>کاتالوگ قیمت عمده</h2></div><span><?=money(count($products))?> محصول</span></div><form class="panel wholesale-filter" action="/wholesale-panel"><label>جست‌وجوی نام یا دسته<input name="q" value="<?=h($q)?>" placeholder="مثلاً کیسه فریزر"></label><label>دسته‌بندی<select name="category"><option value="0">همه دسته‌ها</option><?php foreach(seo_categories()as$c):?><option value="<?=$c['id']?>" <?=$category===(int)$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><button class="btn">نمایش</button><?php if($q!==''||$category):?><a class="btn outline" href="/wholesale-panel">حذف فیلتر</a><?php endif;?></form><div class="product-grid wholesale-products"><?php foreach($products as$p):?><article class="panel wholesale-product"><a href="/products/<?=h($p['slug'])?>"><img src="<?=h($p['image'])?>" alt="<?=h($p['name'])?>" width="240" height="180" loading="lazy"><span class="muted"><?=h($p['category_name'])?></span><h2><?=h($p['name'])?></h2></a><div class="wholesale-price"><small>قیمت مصرف‌کننده</small><del><?=money($p['retail'])?> تومان</del><small>قیمت عمده</small><strong><?=money($p['wholesale'])?> تومان</strong></div><p>قیمت عمده از <?=money($p['minimum'])?> <?=h($p['unit'])?> خودکار اعمال می‌شود؛ صرفه‌جویی هر واحد <?=money((int)$p['retail']-(int)$p['wholesale'])?> تومان است.</p><p class="stock-state <?=$p['stock']?'in-stock':'out-stock'?>"><?=$p['stock']?'موجود · '.money($p['stock']).' '.$p['unit']:'ناموجود'?></p><?php quantity_control($p,true);?></article><?php endforeach;if(!$products):?><div class="empty-state"><h3>محصولی با این فیلتر پیدا نشد</h3><a class="btn" href="/wholesale-panel">نمایش همه محصولات عمده</a></div><?php endif;?></div></section>
 <section id="recent-orders" class="panel wholesale-orders"><div class="section-heading"><h2>سفارش‌های اخیر</h2><a href="/account">همه سفارش‌ها ←</a></div><?php if($orders):?><div class="table-scroll"><table><thead><tr><th>کد سفارش</th><th>تاریخ</th><th>وضعیت</th><th>مبلغ</th><th></th></tr></thead><tbody><?php foreach($orders as$order):?><tr><td dir="ltr"><?=h($order['code'])?></td><td><?=h(substr($order['created_at'],0,10))?></td><td><span class="status"><?=h(order_status($order['status']))?></span></td><td><?=money($order['total'])?> تومان</td><td><a href="/track?code=<?=h($order['code'])?>">پیگیری</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state compact"><h3>هنوز سفارش عمده‌ای ندارید</h3><p>از سفارش سریع، تعداد کالاها را به سبد اضافه کنید.</p><a class="btn" href="#quick-order">شروع سفارش</a></div><?php endif;?></section>
 <section class="panel wholesale-help"><div><h2>برای سفارش ویژه یا حجم بالا نیاز به راهنمایی دارید؟</h2><p>مشخصات محصول، مقدار و مقصد را برای پشتیبانی ارسال کنید. شرایطی که هنوز در سایت درج نشده باید پیش از پرداخت تأیید شود.</p></div><a class="btn" href="/contact">مشاوره خرید عمده</a></section></div><?php page_footer();
}
