function faq_page(): void {
 $all=shop_faq();$faq=array_values(array_filter($all,fn($q)=>$q['answer']!==''));page_header('پرسش‌های متداول خرید و فروش عمده','پاسخ پرسش‌های خرید عمده نایلکس، حداقل سفارش، قیمت همکاری و پرداخت.',true,url('/faq'));
 json_ld(['@context'=>'https://schema.org','@type'=>'FAQPage','mainEntity'=>array_map(fn($q)=>['@type'=>'Question','name'=>$q['question'],'acceptedAnswer'=>['@type'=>'Answer','text'=>$q['answer']]],$faq)]);
 ?><div class="container page-content"><article class="panel prose"><h1>پرسش‌های متداول</h1><section class="buying-faq"><h2>پیش از خرید بدانید</h2><?php foreach($faq as$q):?><details><summary><?=h($q['question'])?></summary><?php editable_text('faq.'.$q['key'],'پاسخ: '.$q['question'],$q['answer']);?></details><?php endforeach;?></section><?php if((current_user()['role']??'')==='ADMIN'):?><section class="seo-content"><h2>پاسخ‌های تکمیل‌نشده</h2><p>این موارد برای مشتری و Schema منتشر نشده‌اند. پس از ذخیره پاسخ، منتشر می‌شوند.</p><?php foreach($all as$q):if($q['answer']===''):?><h3><?=h($q['question'])?></h3><?php editable_text('faq.'.$q['key'],'پاسخ: '.$q['question'],'');endif;endforeach;?></section><?php endif;?><a class="btn" href="/wholesale">خرید عمده</a> <a class="text-link" href="/contact">تماس و پشتیبانی</a></article></div><?php page_footer();
}
